const spans = [
  { id: "a", parent: null, name: "POST /tasks", ms: 65 },
  { id: "b", parent: "a", name: "validate", ms: 2 },
  { id: "c", parent: "a", name: "db.insert", ms: 45 },
  { id: "d", parent: "a", name: "events.publish", ms: 13 },
];

function slowestChild(spans, rootName) {
  const root = spans.find((s) => s.name === rootName);
  const children = spans.filter((s) => s.parent === root.id);
  const slowest = children.reduce((max, s) => (s.ms > max.ms ? s : max));
  return slowest.name;
}

console.log(slowestChild(spans, "POST /tasks"));

